quests[8653] = { id = 8653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Goldbrunn", sourceObjective = "Es ist gut zu wissen, dass die Bewohner dieser Welt noch immer die alten Völker verehren und sie nicht vergessen haben. Ich erbiete Euch meinen Respekt, {name}. Nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[8654] = { id = 8654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Urstein", sourceObjective = "Es ist gut zu wissen, dass die Bewohner dieser Welt noch immer die alten Völker verehren und sie nicht vergessen haben. Ich erbiete Euch meinen Respekt, {name}. Nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[8655] = { id = 8655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schienbeinschützer des Rächers", description = "Qirajimagie ist sehr stark und uralt. Die mächtigsten Qiraji handhaben Gegenstände, die so machtvoll sind, dass sie sogar einem Drachen Einhalt gebieten.\n\nBringt mir die Dominanzbindungen der Qiraji sowie andere geringfügigere Bestandteile und ich werde ein Paar mächtige Stiefel für Euch herstellen.\n\nIhr werdet sie im Kampf gegen den Feind als nützlich empfinden.", sourceObjective = "Bringt die Dominanzbindungen der Qiraji, 2 Götzen der Weisen, 5 Bronzeskarabäen und 5 Tonskarabäen zu Kandrostrasz in Ahn'Qiraj. Diese Aufgabe erfordert auch einen neutralen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Gegenstände erlangt, {name}?", completion = "Das habt Ihr gut gemacht, {name}. Ihr habt bewiesen, dass Ihr kein gewöhnlicher Sterblicher seid.\n\nIch gebe Euch dies hier mit Zuversicht, auf dass sie Euch beim Niederschmettern der bösartigen Qiraji behilflich sein werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[8656] = { id = 8656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halsberge des Hetzers", description = "Der unaussprechliche Alte Gott erwacht langsam aus seinem Schlummer unterhalb Ahn'Qirajs. Das schreckliche Schicksal, das Azeroth erwartet, könnte in Tagen oder auch Jahren Wirklichkeit werden, Zeit spielt für Wesen seiner Macht keine Rolle.\n\nStehen die Sterne günstig, wird er furchtbaren Zorn gegen alle Lebewesen walten lassen. Ihr müsst dem zuvorkommen und einen Weg finden, um seiner Existenz ein Ende zu bereiten.\n\nTut dies und bringt mir ein Stück seiner Hülle. Ich werde Euch eine Rüstung gewähren, die noch kein Sterblicher getragen hat... Rüstung für einen Helden, der einen Gott bezwungen hat!", sourceObjective = "Bringt den Knochenpanzer des Alten Gottes, 2 Götzen des Lebens, 5 Goldskarabäen und 5 Tonskarabäen zu Vethsera innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf bei der Brut Nozdormus.", progress = "Der furchtbare C'Thun wartet ruhend in seiner Behausung in Ahn'Qiraj.", completion = "Ich habe nicht erwartet, dass Ihr von Eurer Unternehmung zurückkehrt, {name}.\n\nIhr habt eine größere Vorsehung erfüllt als die der meisten sterblichen Wesen.\n\nIndem Ihr C'Thun bezwungen habt, habt Ihr nicht nur ganz Azeroth gerettet, sondern auch kosmische Ereignisse in Gang gesetzt, die weit über Eurem Vorstellungsvermögen liegen.\n\nNehmt diese Brustplatte als Zeichen des Ruhms und der Bürde an, die Euch in Folge Eurer Taten erwarten werden.\n\nMöge ihre Macht bei Euren zukünftigen Herausforderungen mit Euch sein, Göttertöter!", sourceObjectiveStatus = "unverified-source-field" }
quests[8657] = { id = 8657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diadem des Hetzers", description = "Die Zwillingsimperatoren... ihr unaufhörliches Flüstern martert langsam meinen Verstand. Sie verhöhnen mich, wissend, dass ich nicht tiefer in ihr Reich vordringen kann, um meinen Bruder Arygos zu retten.\n\nIn meinen Visionen sehe ich ihre monströsen Fratzen, die mit mächtigen Kronen geschmückt sind. Ich werde meine Vergeltung noch bekommen... ich werde diese Symbole der Qirajimacht in solche verwandeln, die unserem Nutzen gerecht werden.\n\nBringt mir die benötigten Bestandteile, {name}. Ich werde Euch dafür ein Kopfstück von unvergleichlicher Macht geben.", sourceObjective = "Bringt Vek'lors Diadem, 2 Götzen des Kampfes, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Bestandteile beschafft, {name}?", completion = "Ihr seid erfolgreich gewesen! Das Flüstern der Zwillingsimperatoren ist verstummt.\n\nNehmt dies als Belohnung. Der bloße Anblick hiervon wird Furcht in die Herzen der Qiraji treiben... es soll sie an ihre gefallenen Anführer erinnern und an den Sterblichen, der sie niederstreckte.", sourceObjectiveStatus = "unverified-source-field" }
quests[8658] = { id = 8658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gamaschen des Hetzers", description = "Ihr möchtet Euch also uns gegenüber bewähren, Sterblicher? Nun gut, vielleicht können wir uns ja gegenseitig helfen.\n\nDer uralte Sandwurm, Ouro, ist ein Geschöpf von legendärer Macht. Man sagt, dass er von dem Alten Gott selbst als Gespött des Lebens erschaffen wurde.\n\nSeine Haut ist unnatürlich... dick, fast unbezwingbar und dennoch flexibel, was ihm ermöglicht, sich mit der Geschwindigkeit und Grazie eines kleineren Lebewesens zu bewegen.\n\nBringt mir eine Probe seiner Haut sowie andere geringfügigere Bestandteile und ich werde mächtige Gamaschen für Euch herstellen.", sourceObjective = "Bringt die Haut des großen Sandwurms, 2 Götzen der Sonne, 5 Silberskarabäen und 5 Knochenskarabäen zu Kandrostrasz innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Bestandteile beschafft, {name}?", completion = "Ja... die Haut des Wurms wird eine wunderbar schützende Schicht abgeben. In Verbindung mit den stärksten Teilen der Qiraji, die wir auf unserem Weg hierher zerstört haben, sollte dies eine prächtige Rüstung abgeben. Möge sie Euch bei der Begegnung des unaussprechlichen Grauens helfen, das Euch im Innern erwarten wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[8659] = { id = 8659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schulterstücke des Hetzers", description = "Man sagt unter uns, dass die kunstvoll verzierten Schulterpanzerungen, die von den sterblichen Völkern getragen werden, zu Beginn eine Nachahmung von Drachenflügeln werden sollten.\n\nBringt mir die Bindungen, die von den höchsten Anführern der Qiraji getragen werden und ich werde sie in ein Paar Schulterstücke verarbeiten, die furchteinflößender als die Flügel Nefarians selbst sind!", sourceObjective = "Bringt die Befehlsbindungen der Qiraji, 2 Götzen des Krieges, 5 Kristallskarabäen und 5 Elfenbeinskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen neutralen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Bestandteile gesammelt?", completion = "Ich werde diese Schulterstücke aus dem Material, das Ihr mir gebracht habt, und den Schuppen der gefallenen Qirajifeinde herstellen, Sterblicher. Mögen sie Euch den Schutz geben, den Ihr braucht, und möge ihr Anblick unseren Feinden Furcht einflößen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8660] = { id = 8660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fußlappen des Verdammnisrufers", description = "Qirajimagie ist sehr stark und uralt. Die mächtigsten Qiraji handhaben Gegenstände, die so machtvoll sind, dass sie sogar einem Drachen Einhalt gebieten.\n\nBringt mir die Dominanzbindungen der Qiraji sowie andere geringfügigere Bestandteile und ich werde ein Paar mächtige Stiefel für Euch herstellen.\n\nIhr werdet sie im Kampf gegen den Feind als nützlich empfinden.", sourceObjective = "Bringt die Dominanzbindungen der Qiraji, 2 Götzen der Nacht, 5 Tonskarabäen und 5 Elfenbeinskarabäen zu Kandrostrasz in Ahn'Qiraj. Diese Aufgabe erfordert auch einen neutralen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Gegenstände erlangt, {name}?", completion = "Das habt Ihr gut gemacht, {name}. Ihr habt bewiesen, dass Ihr kein gewöhnlicher Sterblicher seid.\n\nIch gebe Euch dies hier mit Zuversicht, auf dass sie Euch beim Niederschmettern der bösartigen Qiraji behilflich sein werden.", sourceObjectiveStatus = "unverified-source-field" }
