quests[8666] = { id = 8666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weste der Genesis", description = "Der unaussprechliche Alte Gott erwacht langsam aus seinem Schlummer unterhalb Ahn'Qirajs. Das schreckliche Schicksal, das Azeroth erwartet, könnte in Tagen oder auch Jahren Wirklichkeit werden, Zeit spielt für Wesen seiner Macht keine Rolle.\n\nStehen die Sterne günstig, wird er furchtbaren Zorn gegen alle Lebewesen walten lassen. Ihr müsst dem zuvorkommen und einen Weg finden, um seiner Existenz ein Ende zu bereiten.\n\nTut dies und bringt mir ein Stück seiner Hülle. Ich werde Euch eine Rüstung gewähren, die noch kein Sterblicher getragen hat... Rüstung für einen Helden, der einen Gott bezwungen hat!", sourceObjective = "Bringt die Hülle des Alten Gottes, 2 Götzen der Wiedergeburt, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Vethsera innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf bei der Brut Nozdormus.", progress = "Der furchtbare C'Thun wartet ruhend in seiner Behausung in Ahn'Qiraj.", completion = "Ich habe nicht erwartet, dass Ihr von Eurer Unternehmung zurückkehrt, {name}.\n\nIhr habt eine größere Vorsehung erfüllt als die der meisten sterblichen Wesen.\n\nIndem Ihr C'Thun bezwungen habt, habt Ihr nicht nur ganz Azeroth gerettet, sondern auch kosmische Ereignisse in Gang gesetzt, die weit über Eurem Vorstellungsvermögen liegen.\n\nNehmt diese Brustplatte als Zeichen des Ruhms und der Bürde an, die Euch in Folge Eurer Taten erwarten werden.\n\nMöge ihre Macht bei Euren zukünftigen Herausforderungen mit Euch sein, Göttertöter!", sourceObjectiveStatus = "unverified-source-field" }
quests[8667] = { id = 8667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helm der Genesis", description = "Die Zwillingsimperatoren... ihr unaufhörliches Flüstern martert langsam meinen Verstand. Sie verhöhnen mich, wissend, dass ich nicht tiefer in ihr Reich vordringen kann, um meinen Bruder Arygos zu retten.\n\nIn meinen Visionen sehe ich ihre monströsen Fratzen, die mit mächtigen Kronen geschmückt sind. Ich werde meine Vergeltung noch bekommen... ich werde diese Symbole der Qirajimacht in solche verwandeln, die unserem Nutzen gerecht werden.\n\nBringt mir die benötigten Bestandteile, {name}. Ich werde Euch dafür ein Kopfstück von unvergleichlicher Macht geben.", sourceObjective = "Bringt Vek'lors Diadem, 2 Götzen des Lebens, 5 Goldskarabäen und 5 Tonskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Bestandteile beschafft, {name}?", completion = "Ihr seid erfolgreich gewesen! Das Flüstern der Zwillingsimperatoren ist verstummt.\n\nNehmt dies als Belohnung. Der bloße Anblick hiervon wird Furcht in die Herzen der Qiraji treiben... es soll sie an ihre gefallenen Anführer erinnern und an den Sterblichen, der sie niederstreckte.", sourceObjectiveStatus = "unverified-source-field" }
quests[8668] = { id = 8668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beinkleider der Genesis", description = "Ihr möchtet Euch also uns gegenüber bewähren, Sterblicher? Nun gut, vielleicht können wir uns ja gegenseitig helfen.\n\nDer uralte Sandwurm, Ouro, ist ein Geschöpf von legendärer Macht. Man sagt, dass er von dem Alten Gott selbst als Gespött des Lebens erschaffen wurde.\n\nSeine Haut ist unnatürlich... dick, fast unbezwingbar und dennoch flexibel, was ihm ermöglicht, sich mit der Geschwindigkeit und Grazie eines kleineren Lebewesens zu bewegen.\n\nBringt mir eine Probe seiner Haut sowie andere geringfügigere Bestandteile und ich werde mächtige Gamaschen für Euch herstellen.", sourceObjective = "Bringt die Haut des großen Sandwurms, 2 Götzen des Krieges, 5 Steinskarabäen und 5 Kristallskarabäen zu Kandrostrasz innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Bestandteile beschafft, {name}?", completion = "Ja... die Haut des Wurms wird eine wunderbar schützende Schicht abgeben. In Verbindung mit den stärksten Teilen der Qiraji, die wir auf unserem Weg hierher zerstört haben, sollte dies eine prächtige Rüstung abgeben. Möge sie Euch bei der Begegnung des unaussprechlichen Grauens helfen, das Euch im Innern erwarten wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[8669] = { id = 8669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schulterpolster der Genesis", description = "Man sagt unter uns, dass die kunstvoll verzierten Schulterpanzerungen, die von den sterblichen Völkern getragen werden, zu Beginn eine Nachahmung von Drachenflügeln werden sollten.\n\nBringt mir die Bindungen, die von den höchsten Anführern der Qiraji getragen werden und ich werde sie in ein Paar Schulterstücke verarbeiten, die furchteinflößender als die Flügel Nefarians selbst sind!", sourceObjective = "Bringt die Dominanzbindungen der Qiraji, 2 Götzen des Kampfes, 5 Goldskarabäen und 5 Knochenskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen neutralen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Bestandteile gesammelt?", completion = "Ich werde diese Schulterstücke aus dem Material, das Ihr mir gebracht habt, und den Schuppen der gefallenen Qirajifeinde herstellen, Sterblicher. Mögen sie Euch den Schutz geben, den Ihr braucht, und möge ihr Anblick unseren Feinden Furcht einflößen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8670] = { id = 8670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahnin Runentotem", sourceObjective = "Ich spüre das Feuer des Lebens in Euch, {class}. Ich akzeptiere Eure Ehrerbietung! Nehmt dies als Zeichen meiner Dankbarkeit...", sourceObjectiveStatus = "unverified-source-field" }
