quests[8704] = { id = 8704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel des unsichtbaren Pfads", description = "Man sagt, dass die Ringe, die von den Leutnants der Qiraji getragen werden, ungeheure Fähigkeiten verleihen. Die verderbten Edelsteine, mit denen sie verziert sind, könnten theoretisch mit reinerem Material ausgetauscht werden, um unbefleckte Versionen der Ringe herzustellen.\n\nDie Edelsteine, die die Götzen der Qiraji schmücken, würden sich dafür gut eignen, da sie von besserer Qualität sind.\n\nBringt mir den Ring und Götzen und ich werde einen mächtigen Ring für Euch anfertigen, {class}.", sourceObjective = "Bringt 1 Gebieterring der Qiraji, 2 Bernsteingötzen, 5 Goldskarabäen und 5 Tonskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.", progress = "Habt Ihr mir den Ring und die Gegenstände besorgt, {name}?", completion = "Ich werde den Edelstein auf dem Ring für Euch austauschen. Ihr werdet sehen, dass der Effekt viel... angenehmer ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[8705] = { id = 8705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammer der unendlichen Weisheit", description = "Die Qiraji und ihre Diener besitzen Gegenstände, die aus dem seltensten und feinsten Material hergestellt werden: Knochen von riesengroßen uralten Kreaturen, Edelsteine aus den Tiefen der Erde, reines und starkes Metall.\n\nAllein der Anblick dieser Qirajiartefakte erfüllt mich mit dem Drang, mein Handwerk an ihren zerschmetterten und geschmolzenen Stücken auszuüben. Beweist dem Zirkel Eure Loyalität, {name}, und ich werde aus den feinsten Qirajibestandteilen eine mächtige Waffe für Euch herstellen.", sourceObjective = "Bringt 1 verschnörkelten Griff der Qiraji, 2 züngelnde Götzen, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius.", progress = "Habt Ihr mir die benötigten Bestandteile gebracht, {name}?", completion = "Das habt Ihr gut gemacht, {class}. Dies ist ein Meisterstück... die Balance ist perfekt.\n\nNehmt Eure Waffe, {name}. Schwingt sie zuversichtlich und vernichtet unsere Feinde!", sourceObjectiveStatus = "unverified-source-field" }
quests[8706] = { id = 8706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammer der aufziehenden Stürme", description = "Die Qiraji und ihre Diener besitzen Gegenstände, die aus dem seltensten und feinsten Material hergestellt werden: Knochen von riesengroßen uralten Kreaturen, Edelsteine aus den Tiefen der Erde, reines und starkes Metall.\n\nAllein der Anblick dieser Qirajiartefakte erfüllt mich mit dem Drang, mein Handwerk an ihren zerschmetterten und geschmolzenen Stücken auszuüben. Beweist dem Zirkel Eure Loyalität, {name}, und ich werde aus den feinsten Qirajibestandteilen eine mächtige Waffe für Euch herstellen.", sourceObjective = "Bringt 1 Stachelgriff der Qiraji, 2 Bernsteingötzen, 5 Elfenbeinskarabäen und 5 Bronzeskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius.", progress = "Habt Ihr mir die benötigten Bestandteile gebracht, {name}?", completion = "Das habt Ihr gut gemacht, {class}. Dies ist ein Meisterstück... die Balance ist perfekt.\n\nNehmt Eure Waffe, {name}. Schwingt sie zuversichtlich und vernichtet unsere Feinde!", sourceObjectiveStatus = "unverified-source-field" }
quests[8707] = { id = 8707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klinge der behüteten Geheimnisse", description = "Die Qiraji und ihre Diener besitzen Gegenstände, die aus dem seltensten und feinsten Material hergestellt werden: Knochen von riesengroßen uralten Kreaturen, Edelsteine aus den Tiefen der Erde, reines und starkes Metall.\n\nAllein der Anblick dieser Qirajiartefakte erfüllt mich mit dem Drang, mein Handwerk an ihren zerschmetterten und geschmolzenen Stücken auszuüben. Beweist dem Zirkel Eure Loyalität, {name}, und ich werde aus den feinsten Qirajibestandteilen eine mächtige Waffe für Euch herstellen.", sourceObjective = "Bringt 1 verschnörkelten Griff der Qiraji, 2 Obsidiangötzen, 5 Silberskarabäen und 5 Knochenskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius.", progress = "Habt Ihr mir die benötigten Bestandteile gebracht, {name}?", completion = "Das habt Ihr gut gemacht, {class}. Dies ist ein Meisterstück... die Balance ist perfekt.\n\nNehmt Eure Waffe, {name}. Schwingt sie zuversichtlich und vernichtet unsere Feinde!", sourceObjectiveStatus = "unverified-source-field" }
quests[8708] = { id = 8708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Streitkolben des endlosen Lebens", description = "Die Qiraji und ihre Diener besitzen Gegenstände, die aus dem seltensten und feinsten Material hergestellt werden: Knochen von riesengroßen uralten Kreaturen, Edelsteine aus den Tiefen der Erde, reines und starkes Metall.\n\nAllein der Anblick dieser Qirajiartefakte erfüllt mich mit dem Drang, mein Handwerk an ihren zerschmetterten und geschmolzenen Stücken auszuüben. Beweist dem Zirkel Eure Loyalität, {name}, und ich werde aus den feinsten Qirajibestandteilen eine mächtige Waffe für Euch herstellen.", sourceObjective = "Bringt 1 verschnörkelten Griff der Qiraji, 2 Jaspisgötzen, 5 Kristallskarabäen und 5 Steinskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius.", progress = "Habt Ihr mir die benötigten Bestandteile gebracht, {name}?", completion = "Das habt Ihr gut gemacht, {class}. Dies ist ein Meisterstück... die Balance ist perfekt.\n\nNehmt Eure Waffe, {name}. Schwingt sie zuversichtlich und vernichtet unsere Feinde!", sourceObjectiveStatus = "unverified-source-field" }
