quests[8728] = { id = 8728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gute und die schlechte Nachricht", description = "Das hat ein wenig länger gedauert als erwartet. Nun lasst mich sehen, was dieses Buch zu berichten hat.\n\n<Leise vor sich hermurmelnd beginnt Narain das Buch zu lesen.>\n\nDie gute Nachricht ist, dass ich mir zu 99% sicher bin, eine Arkanitboje konstruieren zu können, die voll und ganz Euren Anforderungen entspricht. Kommen wir zur schlechten Nachricht: Ich brauche eine gehörige Menge Arkanit, Elementiumerz und Edelsteine.\n\nSobald Ihr mir diese Materialien gebracht habt, kann ich mit der Konstruktion der Boje beginnen.", sourceObjective = "Narain Pfauentraum in Tanaris möchte, dass Ihr ihm 20 Arkanitbarren, 10 Elementiumerz, 10 Azerothische Diamanten und 10 blaue Saphire bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[8729] = { id = 8729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn von Neptulon", description = "Hatte ich die schlechte Neuigkeit schon zur Sprache gebracht? Sein Name ist \"Der weiße Riese\": Dreißig Meter Tod und Zerstörung pur. Den kleinen Leckerbissen hatte ich glatt vergessen.\n\nMeinen gnomischen Superpsychokräften nach zu urteilen, befindet sich der beste Ort, um diese Boje zu platzieren, an der Küste Azsharas in der Bucht der Stürme.\n\nHaltet nach einem wirbelnden Mahlstrom Ausschau. Vermutlich ist die ganze Gegend mit Wrackteilen übersät.\n\nMacht es gut und nehmt ein paar Freunde mit.\n\nFalls Ihr die ganze Sache wie durch ein Wunder überleben solltet, bringt den Szeptersplitter zu Anachronos.", sourceObjective = "Benutzt die Arkanitboje am wirbelnden Mahlstrom in der Bucht der Stürme in Azshara.", sourceObjectiveStatus = "unverified-source-field" }
quests[8730] = { id = 8730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nefarius' Verderbnis", description = "Held, seid Ihr es? Es ist tausend Jahre her, seitdem man mir den Splitter anvertraut hat. Jetzt, in meiner finstersten Stunde soll jemand erscheinen, um mich davon zu entlasten... aber was wäre eine Tragödie ohne Grausamkeit?\n\n<Vaelastrasz hustet geschwächt.>\n\nNe... Nefarius besitzt nun den Szeptersplitter.\n\nDie Zeit ist entscheidend. Nefarius hat vor den Splitter zu zerstören. Ihr müsst Euch beeilen!", sourceObjective = "Tötet Nefarian und bringt den roten Szeptersplitter wieder in Euren Besitz. Bringt den roten Szeptersplitter zu Anachronos in den Höhlen der Zeit in Tanaris. Euch bleiben 5 Stunden, um diese Aufgabe zu erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8731] = { id = 8731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Duty" }
quests[8732] = { id = 8732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felddienstpapiere" }
quests[8733] = { id = 8733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eranikus, der Tyrann des Traums", description = "Dies ist der Weg der Begleichung, Held. Würde ich heute getötet werden, dann würde ich für den gerechten Zweck sterben. Ihr müsst den grünen Szeptersplitter wiedererlangen. Ihr müsst Eranikus von der Besudelung, die die Alten Götter über ihn verhängt haben, reinigen.\n\nReist nach Darnassus. Ihr werdet einen meiner Agenten genau vor den Stadtmauern finden. Dieser Agent wird die Dinge für uns in Bewegung setzen und Tyrande über unsere Pläne informieren, ohne Hirschhaupt zu alarmieren.\n\n<Malfurion seufzt.>\n\nEin Bruch mit der in tausend Jahren geschaffenen Gunst...", sourceObjective = "Reist nach Teldrassil und sucht Malfurions Agenten irgendwo außerhalb der Stadtmauern von Darnassus auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[8734] = { id = 8734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tyrande und Remulos", description = "Tyrande wird benachrichtigt, Sterblicher. Shan'do Sturmgrimm hat mich für diesen Fall vorbereitet.\n\nIhr müsst jetzt zur Mondlichtung reisen und mit Remulos sprechen. Er wird weitere Anweisungen bezüglich der Herbeirufung von Eranikus haben.\n\nWir alle wünschen Euch viel Glück.", sourceObjective = "Reist zur Mondlichtung und sprecht mit Bewahrer Remulos.", sourceObjectiveStatus = "unverified-source-field" }
quests[8735] = { id = 8735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verderbnis des Alptraums", description = "Ihr müsst zu den vier Traumportalen von Azeroth reisen und Euch jeweils ein Verderbnisfragment des Alptraums beschaffen. Die Drachkin, die in dieser Gegend hausen, werden derartige Fragmente bei sich tragen. Kommt zu mir zurück, sobald Ihr diese Fragmente eingesammelt habt.", sourceObjective = "Reist zu den vier Portalen des smaragdgrünen Traums in Azeroth und sammelt dort jeweils ein Verderbnisfragment des Alptraums ein. Kehrt zu Bewahrer Remulos bei der Mondlichtung zurück, sobald Ihr diese Aufgabe erfüllt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[8736] = { id = 8736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Alptraum offenbart sich", description = "Wir müssen gegen Eranikus mit Bedacht vorgehen. Wir sollen ihn erlösen und nicht zerstören.\n\nTyrande ist bereits auf dem Weg, um uns bei dieser Aufgabe zu unterstützen. Wir müssen die Attacken des Drachen überstehen und Nachthafen vor der sicheren Zerstörung bewahren.\n\nSeid auf der Hut! Ihr und Eure Verbündeten seid unsere einzige Hoffnung.", sourceObjective = "Verteidigt Nachthafen gegen Eranikus. Bewahrer Remulos darf dabei nicht ums Leben kommen und Eranikus darf nicht getötet werden. Verteidigt Euch. Erwartet Tyrande.", sourceObjectiveStatus = "unverified-source-field" }
quests[8737] = { id = 8737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azurblauer Templer", description = "Die Schattenhammerkultisten und die von ihnen verehrten Elementarfürsten stellen eine dauerhafte Bedrohung für unsere Operationen in Silithus dar. Trotz der neuen Gegnermassen in Ahn'Qiraj können wir es uns nicht erlauben, unsere Wachposten und Einsätze gegen den äußeren Feind zu verringern.\n\nFindet einen Weg, um einen azurblauen Templer auf unsere Existenzebene zu beschwören und zerstört ihn.", sourceObjective = "Beschwört und vernichtet einen azurblauen Templer. Erstattet anschließend Bericht bei Bor Wildmähne auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz I, um diese Aufgabe abschließen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[8738] = { id = 8738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späherbericht des Regalschwarms", description = "Wir haben unsere besten Späher bis weit in die Schwarmbauten der Silithiden ausgesendet, um Informationen zu sammeln. Späher Landion hat die Aktivitäten der Silithiden im Regalschwarm nun schon seit Tagen beobachtet. Findet ihn und besorgt Euch einen schriftlichen Bericht. Wir müssen so schnell wie möglich auf diese Informationen reagieren können, {name}.", sourceObjective = "Setzt Euch mit dem cenarischen Späher Landion innerhalb des Regalschwarmbaus in Verbindung und bringt den Späherbericht des Regalschwarms zu Windruferin Prachthorn auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz VII, um diese Aufgabe abschließen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[8739] = { id = 8739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späherbericht des Ashischwarms", description = "Wir haben unsere besten Späher bis weit in die Schwarmbauten der Silithiden ausgesendet. Späherin Jalia hat die Aktivitäten der Silithiden im Ashischwarm nun schon seit Tagen beobachtet. Findet sie und besorgt Euch einen schriftlichen Bericht. Wir müssen so schnell wie möglich auf diese Informationen reagieren können, {name}.", sourceObjective = "Setzt Euch mit der cenarischen Späherin Jalia innerhalb des Ashischwarmbaus in Verbindung und bringt den Späherbericht des Ashischwarms zu Windruferin Prachthorn auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz VIII, um diese Aufgabe abschließen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[8740] = { id = 8740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marodeure des Schattenhammers", description = "Es wurden mehrfach berittene Gruppen des Schattenhammers gesichtet, die außerhalb der Reichweite unserer Truppen in Burg Cenarius kleinere Patrouillen und Karawanen angreifen.\n\nFindet und vernichtet die Zwielichtmarodeure, gemeinsam mit ihrer Anführerin, einer furchterregenden Kriegerin namens Morna. Meldet Euch anschließend bei Windruferin Prachthorn.", sourceObjective = "Tötet Zwielichtmarodeurin Morna und 2 Zwielichtmarodeure. Erstattet anschließend Bericht bei Windruferin Prachthorn. Ihr benötigt auch den taktischen Einsatz IX, um diese Aufgabe abschließen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[8741] = { id = 8741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Held kehrt zurück", description = "Der Bewahrer erwartet Eure Rückkehr, {name}. Bringt den grünen Szeptersplitter zu Anachronos in den Höhlen der Zeit.", sourceObjective = "Bringt den grünen Szeptersplitter zu Anachronos in den Höhlen der Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[8742] = { id = 8742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht von Kalimdor" }
quests[8743] = { id = 8743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlagt den Gong!" }
quests[8744] = { id = 8744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein sorgfältig verpacktes Geschenk", sourceObjective = "Auf dem Kärtchen an diesem Geschenk steht:\n\nAn {name},\n\nmöge Euer Winterfest fröhlich und heiter verlaufen!", sourceObjectiveStatus = "unverified-source-field" }
quests[8745] = { id = 8745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatz des Zeitlosen" }
quests[8746] = { id = 8746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Metzen das Rentier", description = "Es ist eine KATASTROPHE! Metzen das Rentier wurde entführt!\n\nMetzen ist eines von Altvater Winters acht Rentieren - und Eigentum von Kokelwälder. Wir glauben, dass dieser schreckliche, monströse Griesgram, der sich im Vorgebirge des Hügellandes versteckt, ihn entführt hat. Gerade jetzt zur Festzeit können wir hier nicht weg. Bitte findet Metzen, besiegt seine Entführer und bringt ihn zu uns zurück!", sourceObjective = "Befreit Metzen das Rentier aus den Klauen seiner Entführer nahe der Eisfellhöhle im Vorgebirge des Hügellandes.", sourceObjectiveStatus = "unverified-source-field" }
quests[8747] = { id = 8747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Beschützers", completion = "Beeindruckend, kleine Kreatur. Ihr habt eine Menge durchgemacht, um das Vertrauen des bronzenen Drachenschwarms zu erwerben. Eure Hingabe und Selbstaufopferung wurde zur Kenntnis genommen.\n\nDer Siegelring des Beschützers birgt enorme Kräfte in sich, die Euch gegen die Mächte des Bösen helfen werden.\n\nAber seid gewarnt! Habt Ihr erst einmal Euren Pfad gewählt, gibt es kein Zurück mehr." }
quests[8748] = { id = 8748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Beschützers" }
quests[8749] = { id = 8749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Beschützers" }
quests[8750] = { id = 8750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Beschützers" }
quests[8751] = { id = 8751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Beschützer von Kalimdor", progress = "Nie zuvor habe ich solch eine Hingabe, solch ein Durchhaltevermögen gesehen! Der bronzene Drachenschwarm gewährt Euch die mächtigste Verzauberung. Der Zeitlose selbst, hat es befohlen!\n\nÜbergebt mir Euren Siegelring, damit ich seine Kräfte verstärken kann.", completion = "Erhebt Euch, Beschützer von Kalimdor! Zeigt Euch und lasst Euch huldigen!" }
quests[8752] = { id = 8752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Eroberers", completion = "Beeindruckend, kleine Kreatur. Ihr habt eine Menge durchgemacht, um das Vertrauen des bronzenen Drachenschwarms zu erwerben. Eure Hingabe und Selbstaufopferung wurde zur Kenntnis genommen.\n\nDer Siegelring des Eroberers birgt enorme Kräfte in sich, die Euch gegen die Mächte des Bösen helfen werden. Seine Macht wird Eure körperlichen Angriffe um ein Vielfaches verstärken.\n\nAber seid gewarnt! Habt Ihr erst einmal Euren Pfad gewählt, gibt es kein Zurück mehr." }
quests[8753] = { id = 8753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Eroberers" }
quests[8754] = { id = 8754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Eroberers" }
quests[8755] = { id = 8755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Eroberers" }
quests[8756] = { id = 8756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Eroberer der Qiraji", progress = "Selten habe ich solch eine Hingabe, solch ein Durchhaltevermögen gesehen! Der bronzene Drachenschwarm gewährt Euch die mächtigste Verzauberung. Der Zeitlose selbst, hat es befohlen!\n\nÜbergebt mir Euren Siegelring, damit ich seine Kräfte verstärken kann.", completion = "Erhebt Euch, Eroberer der Qiraji! Zeigt Euch und lasst Euch huldigen!" }
quests[8757] = { id = 8757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Herbeirufers", completion = "Beeindruckend, kleine Kreatur. Ihr habt eine Menge durchgemacht, um das Vertrauen des bronzenen Drachenschwarms zu erwerben. Eure Hingabe und Selbstaufopferung wurde zur Kenntnis genommen.\n\nDer Siegelring des Herbeirufers birgt enorme Kräfte in sich, die Euch gegen die Mächte des Bösen helfen werden. Seine Macht wird Eure magischen und natürlichen Fähigkeiten um ein Vielfaches verstärken.\n\nAber seid gewarnt! Habt Ihr erst einmal Euren Pfad gewählt, gibt es kein Zurück mehr." }
quests[8758] = { id = 8758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Herbeirufers" }
