quests[8826] = { id = 8826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zehn Belobigungsabzeichen" }
quests[8827] = { id = 8827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winters Geschenke", description = "Ich habe gehört, dass Altvater Winter mit großzügiger Unterstützung von Kokelwälder für jeden Geschenke unter den Weihnachtsbaum von Eisenschmiede gelegt hat. Wie gerne würde ich mich auf dem Weg machen, doch leider muss ich mich noch um den PX-238 Winterwundervolt kümmern.\n\nIhr solltet dort auf jeden Fall mal vorbeischauen. Ich bin mir sicher, dass Altvater Winter auch einige Geschenke für Euch mitgebracht hat.", sourceObjective = "Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Eisenschmiede.", completion = "Ho, ho, hallo! Ihr seid aus einem ganz bestimmten Grund hier, richtig? Ihr wollt Eure Winterhauchgeschenke endlich öffnen.\n\nNun, macht Euch mal keine Sorgen! Altvater Winter würde doch niemals seinen Liebling {name} vergessen. Schaut einfach unter dem Baum nach, dort findet Ihr Eure Geschenke.\n\nUnd da dies eine Zeit des Gebens ist: Meint Ihr nicht, dass Eure Freunde sich über eines der fantastischen Produkte von Kokelwälder freuen würden?", sourceObjectiveStatus = "unverified-source-field" }
quests[8828] = { id = 8828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winters Geschenke", description = "Ich habe gehört, dass Altvater Winter mit großzügiger Unterstützung von Kokelwälder für jeden Geschenke unter den Weihnachtsbaum von Orgrimmar gelegt hat. Wie gerne würde ich mich auf dem Weg machen, doch leider muss ich mich noch um den PX-238 Winterwundervolt kümmern.\n\nIhr solltet dort auf jeden Fall mal vorbeischauen. Ich bin mir sicher, dass Altvater Winter auch einige Geschenke für Euch mitgebracht hat.", sourceObjective = "Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Orgrimmar.", completion = "Ho, ho, hallo! Ihr seid aus einem ganz bestimmten Grund hier, richtig? Ihr wollt Eure Winterhauchgeschenke endlich öffnen.\n\nNun, macht Euch mal keine Sorgen! Altvater Winter würde doch niemals seinen Liebsten vergessen. Schaut einfach unter dem Baum nach, dort findet Ihr Eure Geschenke.\n\nUnd da dies eine Zeit des Gebens ist: Meint Ihr nicht, dass Eure Freunde sich über einige der fantastischen Produkte von Kokelwälder freuen würden?", sourceObjectiveStatus = "unverified-source-field" }
quests[8829] = { id = 8829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die ultimative Täuschung", description = "Die Anhänger des Schattenhammers operieren in zahllosen geheimen und gut getarnten Gruppen. Während der Kult unsere Welt durch zahllose Aktionen plagt, werden alle Operationen an einem uns immer noch unbekannten Ort geplant.\n\nWir sind zu der Erkenntnis gelangt, dass die Steine, mit denen die Kultisten des Schattenhammers ihre Anführer beschwören, in beide Richtungen funktionieren. Um einen der Steine ohne Gefahr benutzen zu können, werden wir versuchen, die Robe eines Abgesandten des Schattenhammers bis ins kleinste Detail nachzubilden.\n\nBeschafft die dafür benötigten Materialien und bringt sie zu Aurel Goldblatt, {name}.", sourceObjective = "Bringt 1 Schattenhaut, 3 ausgefranste Monstrositätenstickereien und 1 Robe eines Schattenhammerkultisten zu Aurel Goldblatt auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz XI, um diese Aufgabe abschließen zu können.", sourceObjectiveStatus = "unverified-source-field" }
