quests[8855] = { id = 8855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreißig Abzeichen gegen Kriegsmaterial tauschen" }
quests[8856] = { id = 8856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wüstenüberlebenspaket", description = "Seitdem ständig neue Rekruten auf Burg Cenarius eintreffen, stehen wir vor dem Problem, sie in der Wüste am Leben zu erhalten. Der ständige Wasserentzug und die zahlreichen giftigen Kreaturen in dieser Gegend sind eine ernstzunehmende Gefahr für die unerfahren Soldaten. Sammelt alles, was notwendig ist, um ein Wüstenüberlebenspaket zusammenzustellen und bringt die erforderlichen Vorräte zu Calandrath auf Burg Cenarius.", sourceObjective = "Bringt 4 Kugeln des Wassers, 4 mächtige Gegengifte und 4 gebackene Lachse zu Calandrath in der Taverne von Burg Cenarius in Silithus.", sourceObjectiveStatus = "unverified-source-field" }
quests[8857] = { id = 8857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Kolosses - Ashi", description = "Ich suche nach schlachterprobten Abenteurern, die für mich eine Fragmentprobe vom Koloss des Ashischwarms zu Glotz in Beutebucht bringen. Nein, nein, Ihr braucht Euch nicht einmal in die Nähe dieses Giganten zu wagen. Nehmt einfach eine von meinen Proben und beeilt Euch. Verrottet nutzt sie Glotz nicht viel!", sourceObjective = "Bringt das Fragment vom Koloss des Ashischwarms zu Glotz Widrikus in Beutebucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[8858] = { id = 8858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Kolosses - Regal", description = "Ich würde nichts lieber tun, als Schlickfaust dieses verdammte Fragment in sein fettes Maul zu stopfen. Stattdessen stecke ich hier fest und sammle Proben von dieser zu groß geratenen Kakerlake! In Anbetracht ihrer Größe, werde ich hier wohl noch eine Weile beschäftigt sein.\n\nNehmt diese Probe und bringt sie für mich zu Schlickfaust... und beeilt Euch, {class}. Er zahlt auch sehr gut!\n\nAlso, ab zur Thoriumspitze in die Sengende Schlucht.", sourceObjective = "Bringt das Fragment vom Koloss des Regalschwarms zu Aufseher Schlickfaust in die Sengende Schlucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[8859] = { id = 8859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Kolosses - Zora", description = "Meine Leute hätte es beinahe erwischt, als sie diese Probe beschafft haben. Ihr müsst Euch unbedingt beeilen! Lord Maxwell Tyrosus wartet bereits voller Ungeduld auf eine frische Fragmentprobe. Er geht davon aus, dass uns die Geheimnisse dieses Kolosses im Kampf gegen die Geißel sehr von Nutzen sein werden!\n\nWieso seid Ihr noch hier!? Zur Kapelle des Hoffnungsvollen Lichts! Ja, ja, man wird Euch für diese Aufgabe großzügig entlohnen...", sourceObjective = "Bringt das Fragment vom Koloss des Zoraschwarms zu Lord Maxwell Tyrosus an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[8860] = { id = 8860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neujahrsfeier!", description = "In Sturmwind wird das neue Jahr ganz groß gefeiert! Den ganzen Tag lang gibt es kostenlosen Hochprozentigen und nachts ein fantastisches Feuerwerk! Das wird sicher ein Riesenspaß... allerdings findet heute auch in Beutebucht eine Neujahrsfeier statt. Ich wette, dort ist sogar noch mehr los!\n\nEgal! Jedenfalls braucht Gastwirtin Allison in Sturmwind eine Ladung Kokelwälder Festtagsspeisen, um alle Partylöwen satt in das neue Jahr zu bringen. Würdet Ihr mir den Gefallen tun und die Vorräte für mich abliefern?\n\nDanke, {name}! Ihr findet Gastwirtin Allison in der Güldenen Rose, drüben im Handelsdistrikt von Sturmwind.", sourceObjective = "Bringt die Vorräte von Kokelwälder zu Gastwirtin Allison in Sturmwind.", progress = "Seid gegrüßt! Seid Ihr wegen der Feier hier? Oder wollt Ihr einfach Eure müden Knochen etwas ausruhen?", completion = "Oh, meine Vorräte von Kokelwälder! Großartig! Die brauche ich dringend, um all die hungrigen Mäuler während der Feierlichkeiten zu stopfen!\n\nVielen Dank für Eure Hilfe, {name}. Bitte, nehmt dies als Belohnung an und vergesst nicht mit den anderen draußen zu trinken und zu tanzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[8861] = { id = 8861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neujahrsfeier!", description = "In Donnerfels wird das neue Jahr ganz groß gefeiert! Den ganzen Tag lang gibt es kostenlosen Hochprozentigen und nachts ein fantastisches Feuerwerk!\n\nDas wird sicher ein Riesenspaß... allerdings findet auch in Beutebucht eine Neujahrsfeier statt. Ich wette, dort ist sogar noch mehr los!\n\nEgal! Jedenfalls braucht Gastwirtin Pala eine Ladung Kokelwälder Festtagsspeisen, um alle Partylöwen satt in das neue Jahr zu bringen. Würdet Ihr mir den Gefallen tun und die Vorräte für mich abliefern?\n\nDanke, {name}! Ihr findet Gastwirtin Pala in der Taverne nahe der Brücke zur Anhöhe der Jäger.", sourceObjective = "Bringt die Vorräte von Kokelwälder zu Gastwirtin Pala in Donnerfels.", progress = "Guten Tag, {class}! Seid Ihr wegen der Feierlichkeiten nach Donnerfels gekommen? Oder wollt Ihr nur ein wenig Eure von der Jagd müden Hufe ausruhen?", completion = "Oh, sehr gut! Mit diesen Vorräten sollte ich alle Feiernden auf dem Neujahrsfest bewirten können!\n\nIch danke Euch, {name}. Ich stehe in Eurer Schuld. Bitte, nehmt diese Münzen als Dankeschön... und befolgt meinen Rat - nehmt einen herzhaften Schluck aus dem Fass draußen und schließt Euch den anderen beim Feiern des neuen Jahres an!", sourceObjectiveStatus = "unverified-source-field" }
quests[8862] = { id = 8862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Kerze" }
quests[8863] = { id = 8863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festtagsklöße" }
quests[8864] = { id = 8864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festtagskleider des Mondfests" }
quests[8865] = { id = 8865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festliche Hosenanzüge des Mondfests" }
quests[8866] = { id = 8866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Bronzebart", sourceObjective = "Es ist gut zu wissen, dass die Bewohner dieser Welt noch immer die alten Völker verehren und sie nicht vergessen haben. Ich erbiete Euch meinen Respekt, {name}. Nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[8867] = { id = 8867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondfeuerwerk", description = "Die Druiden der Mondlichtung feiern jedes Jahr den großen Triumph unserer Stadt über ein uraltes Übel.\n\nWir ehren die Weisheit unserer Urahnen, nehmen an herrlichen Festgelagen teil und... schießen natürlich Feuerwerk ab!\n\nFür eine kleine Spende könnt Ihr bei unserem Verkäufer farbenfrohe Raketen erwerben. Versucht doch mal eines der hier herumstehenden Startgeräte, {name}.", sourceObjective = "Zündet 8 Raketen und 2 Raketenbündel und kehrt dann zu einer Botin des Mondfests in irgendeiner Hauptstadt zurück.", progress = "Konntet Ihr die Zünder finden, {name}?", completion = "Gut gemacht, {name}.\n\nDa Ihr jetzt in der richtigen Stimmung seid, nehmt doch diese Einladung zu dem Fest auf der Mondlichtung an.\n\nEs sind recht unterhaltsame Feierlichkeiten, falls Ihr etwas Zeit haben solltet. Wir teilen dort miteinander gutes Essen, Getränke, Geschichten und natürlich... noch mehr Feuerwerk!\n\nÖffnet die Einladung, während Ihr innerhalb des Mondlichtkreises steht und Ihr werdet zur Mondlichtung transportiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[8868] = { id = 8868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Segen", description = "Das Biest Omen war einstmals ein bekannter Held. Als ein Wolf von großer Stärke und Geschicklichkeit, kämpfte er im Krieg der Ahnen Seite an Seite mit den Helden dieser Zeit, bis er den dämonischen Mächten verfiel. Sein Hass richtete sich gegen seine einstigen Verbündeten und auf seinem Rachefeldzug durch Azeroth verbreitete er Tod und Verderben.\n\nLetztlich besiegte man ihn hier, in den Landen der Mondlichtung, wo er bis heute auf dem Grund des Sees von Elune'ara ruht. Doch jedes Jahr, während des Neujahrfests, erwacht er zu neuem Leben...\n\nSchart Eure Freunde um Euch! Zieht los, beschwört und besiegt das Biest Omen. Erlangt Elunes Segen!", sourceObjective = "Beschwört Omen, besiegt ihn und erlangt Elunes Segen. Kehrt anschließend zu Valadar Sternensang in Nachthafen zurück.", completion = "Das habt Ihr sehr gut gemacht, {name}. Der Sieg über Omen hat seinen Geist wieder in die Tiefen des Sees von Elune'ara verbannt. Obwohl das Biest durch Elune selbst gesegnet wurde und es dadurch unsterblich ist, wird sein Zorn für ein weiteres Jahr besänftigt sein.\n\nEuer Sieg ist eine Feier, {name} – eine Feier zu Ehren der Macht Omens, Eurer Stärke und der Ausdauer Eurer Verbündeten und nicht zuletzt des Friedens, den Ihr diesem tragischen Held der Vergangenheit geschenkt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[8869] = { id = 8869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Süße Beschaulichkeit", description = "In den Grenzen der Scharlachroten Bastion liegt die süße Beschaulichkeit. Der purpurrote Hammerschmied bewacht das Rezept mit seinem Leben. Besiegt ihn und bringt mir seine Schürze. Dafür werde ich Euch zu einem Hammerschmied ausbilden.\n\nIhr müsst eines wissen: Wenn Ihr Euch für den Weg des Hammerschmieds entschieden habt, sind die Wege des Schwertschmieds und des Axtschmieds nicht mehr verfügbar.", sourceObjective = "Begebt Euch nach Stratholme und tötet den purpurroten Hammerschmied. Nehmt die Schürze des purpurroten Hammerschmiedes und kehrt zu Lilith zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8870] = { id = 8870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mondfest", description = "Es ist mal wieder so weit, {name}! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, gemeinsam mit uns das Mondfest zu feiern. Der Ort, an dem Ihr die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", sourceObjective = "Sprecht mit der Botin des Mondfests im Mystikerviertel von Eisenschmiede. Die Boten in den anderen Hauptstädten können Euch ebenfalls weiterhelfen.", completion = "Seid gegrüßt, {name}. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[8871] = { id = 8871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mondfest", description = "Es ist mal wieder so weit, {name}! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, gemeinsam mit uns das Mondfest zu feiern. Der Ort, an dem Ihr die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", sourceObjective = "Sprecht mit der Botin des Mondfests in Sturmwind.", completion = "Seid gegrüßt, {name}. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[8872] = { id = 8872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mondfest", description = "Es ist mal wieder so weit, {name}! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, gemeinsam mit uns das Mondfest zu feiern. Der Ort, an dem Ihr die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", sourceObjective = "Sprecht mit der Botin des Mondfests in der Enklave des Cenarius in Darnassus. Die Boten in den anderen Hauptstädten können Euch ebenfalls weiterhelfen.", completion = "Seid gegrüßt, {name}. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[8873] = { id = 8873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mondfest", description = "Es ist mal wieder so weit, {name}! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, gemeinsam mit uns das Mondfest zu feiern. Der Ort, an dem Ihr die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", sourceObjective = "Sprecht mit der Botin des Mondfests im Tal der Weisheit in Orgrimmar. Die Boten in den anderen Hauptstädten können Euch ebenfalls weiterhelfen.", completion = "Seid gegrüßt, {name}. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[8874] = { id = 8874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mondfest", description = "Es ist mal wieder so weit, {name}! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, gemeinsam mit uns das Mondfest zu feiern. Der Ort, an dem Ihr die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", sourceObjective = "Sprecht mit der Botin des Mondfests am Eingang zur Unterstadt. Die Boten in den anderen Hauptstädten können Euch ebenfalls weiterhelfen.", completion = "Seid gegrüßt, {name}. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[8875] = { id = 8875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mondfest", description = "Es ist mal wieder so weit, {name}! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, gemeinsam mit uns das Mondfest zu feiern. Der Ort, an dem Ihr die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", sourceObjective = "Sprecht mit der Botin des Mondfests auf der Anhöhe der Ältesten in Donnerfels. Die Boten in den anderen Hauptstädten können Euch ebenfalls weiterhelfen.", completion = "Seid gegrüßt, {name}. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", sourceObjectiveStatus = "unverified-source-field" }
